/bin/bash -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="A little more room for your ideas. Explore Marginalia'"'s free, Pro, and Team note-taking plans.\">
  <meta name=\"theme-color\" content=\"#f8f8f3\">
  <title>Pricing — Marginalia</title>
  <style>
    :root { --paper: #f8f8f3; --ink: #253d32; --muted: #686f66; --line: #dedfd5; --accent: #dbe8b9; }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body { margin: 0; background: var(--paper); color: var(--ink); font-family: Arial, Helvetica, sans-serif; font-size: 15px; -webkit-font-smoothing: antialiased; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; cursor: pointer; }
    a, button, summary { -webkit-tap-highlight-color: transparent; }
    :focus-visible { outline: 3px solid #8a9f5d; outline-offset: 5px; }
    .wrap { width: min(1120px, calc(100% - 80px)); margin-inline: auto; }
    .skip-link { position: absolute; top: -80px; left: 20px; padding: 12px; background: var(--ink); color: white; z-index: 5; }
    .skip-link:focus { top: 15px; }
    .header { border-bottom: 1px solid var(--line); }
    .nav { min-height: 88px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
    .wordmark { display: inline-flex; align-items: center; gap: 10px; font-family: Georgia, 'Times New Roman', serif; font-size: 27px; letter-spacing: -1.1px; }
    .brand-mark { width: 29px; height: 32px; }
    .nav-links, .nav-account { display: flex; align-items: center; gap: 32px; font-size: 13px; }
    .nav-links a { color: var(--muted); position: relative; padding-block: 10px; }
    .nav-links a:hover, .nav-links a[aria-current] { color: var(--ink); }
    .nav-links a[aria-current]::after { content: ''; width: 4px; height: 4px; background: var(--ink); position: absolute; bottom: 0; left: calc(50% - 2px); border-radius: 50%; }
    .signup { border: 1px solid var(--ink); border-radius: 5px; padding: 11px 17px; transition: background .15s; }
    .signup:hover { background: #e9edde; }
    .hero { text-align: center; padding: 66px 0 33px; }
    .eyebrow { font-size: 10px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; margin: 0 0 22px; }
    h1, .section-title { font-family: Georgia, 'Times New Roman', serif; font-weight: 400; letter-spacing: -2.5px; }
    h1 { font-size: clamp(44px, 5.2vw, 65px); line-height: 1.08; margin: 0; }
    h1 em { font-weight: 400; color: #677c4c; }
    .hero-copy { color: var(--muted); font-size: 15px; line-height: 1.7; margin: 20px 0 28px; }
    .billing { display: flex; align-items: center; justify-content: center; gap: 12px; }
    .toggle { display: inline-flex; padding: 4px; border: 1px solid var(--line); border-radius: 7px; background: #eeefe7; }
    .toggle button { border: 0; border-radius: 4px; padding: 10px 21px; color: var(--muted); background: transparent; font-size: 12px; }
    .toggle button[aria-pressed=\"true\"] { background: #fff; color: var(--ink); box-shadow: 0 1px 3px #253d3214; }
    .save { font-size: 11px; color: #526640; background: #e8edda; border-radius: 4px; padding: 6px 8px; }
    .plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; padding-top: 9px; }
    .plan { display: flex; flex-direction: column; border: 1px solid var(--line); border-radius: 9px; padding: 28px; background: #fdfdf9; }
    .plan-top { display: flex; align-items: center; justify-content: space-between; min-height: 27px; margin-bottom: 19px; }
    .plan-icon { width: 25px; height: 25px; stroke-width: 1.4; }
    h2 { margin: 0; }
    .plan h2 { font-family: Georgia, 'Times New Roman', serif; font-size: 29px; font-weight: 400; letter-spacing: -.6px; }
    .desc { margin: 8px 0 24px; color: var(--muted); font-size: 12px; line-height: 1.6; }
    .price { display: flex; align-items: baseline; gap: 7px; min-height: 54px; }
    .amount { font-size: 47px; letter-spacing: -2.5px; line-height: 1.1; }
    .price small { font-size: 11px; color: var(--muted); }
    .billing-note { color: var(--muted); font-size: 11px; margin: 7px 0 22px; min-height: 14px; }
    .btn { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 13px 15px; font-size: 12px; font-weight: 600; border: 1px solid #bfc5b5; border-radius: 4px; transition: background .15s, border-color .15s; }
    .btn:hover { background: #edf0e5; border-color: #89967e; }
    .btn svg { width: 15px; height: 15px; }
    .features-label { font-size: 10px; letter-spacing: 1.1px; margin: 26px 0 13px; text-transform: uppercase; font-weight: 600; }
    .plan ul { list-style: none; padding: 0; margin: 0; }
    .plan li { display: flex; align-items: center; gap: 10px; font-size: 12px; padding: 8px 0; line-height: 1.4; }
    .plan li::before { content: ''; display: block; width: 12px; height: 7px; border-left: 1.4px solid #728458; border-bottom: 1.4px solid #728458; transform: translateY(-2px) rotate(-45deg); flex: 0 0 10px; }
    .plan li.unavailable { color: #858a7f; }
    .plan li.unavailable::before { border: none; height: 1px; background: #a9aea2; transform: none; }
    .popular { background: var(--ink); border-color: var(--ink); color: #f6f7ee; }
    .popular .desc, .popular .billing-note, .popular .price small { color: #c2cdc1; }
    .badge { color: #dce8bf; font-size: 9px; letter-spacing: 1px; text-transform: uppercase; border: 1px solid #647354; padding: 6px 9px; border-radius: 4px; }
    .popular .btn { background: var(--accent); border-color: var(--accent); color: var(--ink); }
    .popular .btn:hover { background: #eaf2d3; }
    .popular .features-label { color: #c2cdc1; }
    .popular li::before { border-color: #bfd695; }
    .popular li.unavailable { color: #b1bcae; }
    .popular li.unavailable::before { background: #869680; }
    .plan-footnote { display: flex; align-items: center; justify-content: center; gap: 7px; color: var(--muted); font-size: 11px; margin: 23px 0 0; }
    .plan-footnote svg { width: 13px; height: 13px; }
    .benefits { margin-top: 60px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 30px 0 33px; }
    .benefits-heading { text-align: center; font-size: 10px; font-weight: 500; letter-spacing: 1.7px; text-transform: uppercase; margin-bottom: 27px; color: var(--muted); }
    .benefit-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 30px; }
    .benefit { display: flex; align-items: flex-start; gap: 14px; padding-inline: 12px; }
    .benefit > svg { width: 22px; height: 22px; flex-shrink: 0; margin-top: 2px; stroke-width: 1.3; }
    .benefit h3 { font-size: 13px; font-weight: 500; margin: 0 0 7px; }
    .benefit p { font-size: 12px; color: var(--muted); line-height: 1.7; margin: 0; }
    .faq { display: grid; grid-template-columns: 1fr 1.45fr; gap: 80px; padding-block: 66px 76px; }
    .faq .eyebrow { margin-bottom: 15px; }
    .section-title { font-size: 39px; line-height: 1.15; letter-spacing: -1.3px; }
    .faq-intro > p:last-child { color: var(--muted); font-size: 12px; line-height: 1.7; margin-top: 15px; }
    details { border-bottom: 1px solid var(--line); }
    details:first-child { border-top: 1px solid var(--line); }
    summary { list-style: none; cursor: pointer; padding: 20px 0; display: flex; align-items: center; justify-content: space-between; gap: 16px; font-size: 13px; }
    summary::-webkit-details-marker { display: none; }
    summary::after { content: '+'; font-size: 20px; font-weight: 400; color: #6b7b59; }
    details[open] summary::after { content: '−'; }
    details p { color: var(--muted); font-size: 12px; line-height: 1.8; margin: -3px 30px 20px 0; }
    .footer { border-top: 1px solid var(--line); }
    .footer-inner { min-height: 91px; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
    .footer .wordmark { font-size: 22px; }
    .footer p { color: var(--muted); font-size: 10px; }
    .footer-note { font-family: Georgia, 'Times New Roman', serif; font-size: 14px; font-style: italic; color: #677c4c; }
    svg { fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; }
    .svg-library { position: absolute; width: 0; height: 0; overflow: hidden; }
    @media (min-width: 1500px) { .hero { padding-top: 82px; } }
    @media (max-width: 900px) {
      .wrap { width: calc(100% - 48px); }
      .nav-links, .nav-account { gap: 20px; }
      .plan { padding: 22px; }
      .plans { gap: 12px; }
      .desc { min-height: 38px; margin-bottom: 17px; }
      .faq { gap: 40px; }
      .benefit { padding-inline: 0; gap: 10px; }
    }
    @media (max-width: 700px) {
      .wrap { width: calc(100% - 36px); }
      .nav { min-height: 76px; flex-wrap: wrap; gap: 13px; padding-block: 17px; }
      .wordmark { font-size: 24px; }
      .brand-mark { width: 24px; height: 27px; }
      .nav-links { order: 3; width: 100%; justify-content: center; gap: 34px; }
      .nav-account { gap: 15px; font-size: 12px; }
      .signup { padding: 9px 11px; }
      .hero { padding: 44px 0 29px; }
      .eyebrow { font-size: 9px; letter-spacing: 1.5px; }
      h1 { font-size: 47px; letter-spacing: -2px; }
      .hero-copy { font-size: 13px; margin: 19px auto 24px; max-width: 290px; }
      .hero-copy br { display: none; }
      .plans { grid-template-columns: 1fr; gap: 16px; max-width: 430px; margin-inline: auto; }
      .plan { padding: 27px; }
      .plan-top { margin-bottom: 14px; }
      .desc { min-height: auto; margin-bottom: 22px; }
      .plan li { font-size: 13px; }
      .plan-footnote { font-size: 10px; }
      .benefits { margin-top: 40px; padding-block: 27px; }
      .benefit-grid { grid-template-columns: 1fr; gap: 25px; max-width: 310px; margin-inline: auto; }
      .benefit { gap: 16px; }
      .faq { grid-template-columns: 1fr; gap: 23px; padding-block: 43px 46px; }
      .section-title { font-size: 35px; }
      .faq-intro > p:last-child { margin-bottom: 0; }
      .footer-inner { flex-wrap: wrap; justify-content: center; padding-block: 25px; gap: 13px 25px; }
      .footer-note { width: 100%; text-align: center; }
      .footer p { margin: 0; }
    }
    @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } *, *::before, *::after { transition: none "'!important; } }
  </style>
</head>
<body>
  <svg class="svg-library" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <defs>
      <symbol id="mark" viewBox="0 0 30 34"><path d="M6 29V5h18v24l-9-5-9 5Z" stroke-width="1.6"/><path d="M11 11h8M11 15h8M11 19h4" stroke-width="1.3"/></symbol>
      <symbol id="arrow" viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5" stroke-width="1.5"/></symbol>
      <symbol id="sprout" viewBox="0 0 24 24"><path d="M12 21V11m0 5C5 17 3 12 3 8c6 0 9 3 9 8Zm0-5c0-5 3-8 9-8 0 6-3 9-9 8Z"/></symbol>
      <symbol id="spark" viewBox="0 0 24 24"><path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6L12 2Z"/></symbol>
      <symbol id="team" viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></symbol>
      <symbol id="lock" viewBox="0 0 24 24"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></symbol>
      <symbol id="bolt" viewBox="0 0 24 24"><path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/></symbol>
      <symbol id="sync" viewBox="0 0 24 24"><path d="M20 8a8 8 0 0 0-14-2L3 9m0-5v5h5m-4 7a8 8 0 0 0 14 2l3-3m0 5v-5h-5"/></symbol>
    </defs>
  </svg>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="header">
    <nav class="nav wrap" aria-label="Main navigation">
      <a href="#" class="wordmark" aria-label="Marginalia home"><svg class="brand-mark" aria-hidden="true"><use href="#mark"/></svg>Marginalia</a>
      <div class="nav-links"><a href="#features">Features</a><a href="#pricing" aria-current="page">Pricing</a><a href="#faq">FAQs</a></div>
      <div class="nav-account"><a href="#">Log in</a><a class="signup" href="#">Start for free <span aria-hidden="true">↗</span></a></div>
    </nav>
  </header>
  <main id="main" class="wrap">
    <section class="hero" aria-labelledby="page-title">
      <p class="eyebrow">A little space for big ideas</p>
      <h1 id="page-title">Good ideas deserve<br><em>room to grow.</em></h1>
      <p class="hero-copy">From your first note to your next big thing.<br>Find a plan that fits the way you think.</p>
      <div class="billing">
        <div class="toggle" role="group" aria-label="Billing period">
          <button type="button" data-billing="monthly" aria-pressed="true">Monthly</button>
          <button type="button" data-billing="yearly" aria-pressed="false">Yearly</button>
        </div>
        <span class="save">Save 20% yearly</span>
      </div>
    </section>
    <section class="plans" id="pricing" aria-label="Compare pricing plans">
      <article class="plan">
        <div class="plan-top"><svg class="plan-icon" aria-hidden="true"><use href="#sprout"/></svg></div>
        <h2>Starter</h2>
        <p class="desc">A home for your everyday thoughts.</p>
        <div class="price"><span class="amount">$0</span><small>/ month</small></div>
        <p class="billing-note">Free, for as long as you like.</p>
        <a class="btn" href="#">Start for free <svg aria-hidden="true"><use href="#arrow"/></svg></a>
        <p class="features-label">The essentials, covered</p>
        <ul>
          <li>Up to 100 notes</li><li>Sync across 2 devices</li><li>Basic search</li><li class="unavailable">Offline access <span class="sr-only">(not included)</span></li><li class="unavailable">Shared notebooks <span class="sr-only">(not included)</span></li>
        </ul>
      </article>
      <article class="plan popular">
        <div class="plan-top"><svg class="plan-icon" aria-hidden="true"><use href="#spark"/></svg><span class="badge">Most popular</span></div>
        <h2>Pro</h2>
        <p class="desc">More room for a mind that never stops.</p>
        <div class="price" aria-live="polite" aria-atomic="true"><span class="amount" data-monthly="8" data-yearly="6.40">$8</span><small>/ month</small></div>
        <p class="billing-note" data-annual="$76.80 billed yearly">Billed monthly. Cancel anytime.</p>
        <a class="btn" href="#">Try Pro for free <svg aria-hidden="true"><use href="#arrow"/></svg></a>
        <p class="features-label">Space to do your best thinking</p>
        <ul>
          <li>Unlimited notes</li><li>Sync across unlimited devices</li><li>Full-text search inside PDFs</li><li>Offline access</li><li class="unavailable">Shared notebooks <span class="sr-only">(not included)</span></li>
        </ul>
      </article>
      <article class="plan">
        <div class="plan-top"><svg class="plan-icon" aria-hidden="true"><use href="#team"/></svg></div>
        <h2>Team</h2>
        <p class="desc">Great thinking happens together.</p>
        <div class="price" aria-live="polite" aria-atomic="true"><span class="amount" data-monthly="14" data-yearly="11.20">$14</span><small>/ user / month</small></div>
        <p class="billing-note" data-annual="$134.40 per user, billed yearly">Billed monthly. Cancel anytime.</p>
        <a class="btn" href="#">Get started with Team <svg aria-hidden="true"><use href="#arrow"/></svg></a>
        <p class="features-label">Everything in Pro, plus</p>
        <ul><li>Shared notebooks</li><li>Admin controls</li><li>Priority support</li><li>Single sign-on (SSO)</li><li>One space for your whole team</li></ul>
      </article>
    </section>
    <p class="plan-footnote"><svg aria-hidden="true"><use href="#lock"/></svg>14 days of Pro, on us. No credit card required.</p>
    <section class="benefits" id="features" aria-labelledby="benefits-title">
      <h2 class="benefits-heading" id="benefits-title">Thoughtfully made. Whichever plan you choose.</h2>
      <div class="benefit-grid">
        <div class="benefit"><svg aria-hidden="true"><use href="#bolt"/></svg><div><h3>Less searching. More thinking.</h3><p>Find the thought you need, right when<br>you need it. Fast by design.</p></div></div>
        <div class="benefit"><svg aria-hidden="true"><use href="#lock"/></svg><div><h3>Your thoughts stay yours.</h3><p>Encrypted and protected. A private<br>place for everything on your mind.</p></div></div>
        <div class="benefit"><svg aria-hidden="true"><use href="#sync"/></svg><div><h3>Pick up where you left off.</h3><p>Your notes, in sync across your devices.<br>At your desk or out in the world.</p></div></div>
      </div>
    </section>
    <section class="faq" id="faq" aria-labelledby="faq-title">
      <div class="faq-intro"><p class="eyebrow">A few helpful answers</p><h2 class="section-title" id="faq-title">Small print.<br>Clear answers.</h2><p>Because choosing a plan should be simple.</p></div>
      <div>
        <details open><summary>Can I cancel anytime?</summary><p>Yes. You can cancel your subscription at any time, with no questions asked.</p></details>
        <details><summary>Is there a free trial for Pro?</summary><p>Yes, Pro comes with a 14-day free trial. No credit card required.</p></details>
        <details><summary>Do you offer student discounts?</summary><p>Students get 50% off Pro with a valid school email.</p></details>
      </div>
    </section>
  </main>
  <footer class="footer"><div class="footer-inner wrap"><a href="#" class="wordmark">Marginalia<span aria-hidden="true">.</span></a><span class="footer-note">A place for your train of thought.</span><p>© 2026 Marginalia Inc. All rights reserved.</p></div></footer>
  <script>
    const billingButtons = document.querySelectorAll('"'[data-billing]');
    billingButtons.forEach(button => {
      button.addEventListener('click', () => {
        const period = button.dataset.billing;
        billingButtons.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
        document.querySelectorAll('[data-monthly]').forEach(price => {
          price.textContent = '"'$'"' + price.dataset[period];
        });
        document.querySelectorAll('[data-annual]').forEach(note => {
          note.textContent = period === 'yearly' ? note.dataset.annual : 'Billed monthly. Cancel anytime.';
        });
      });
    });
  </script>
</body>
</html>
EOF"

